import React from "react";
import { Button, Container, Typography, Box, AppBar, Toolbar } from "@mui/material";
import { useNavigate } from "react-router-dom";

const HomePage = () => {
  const navigate = useNavigate();

  return (
    <Box sx={{ minHeight: "100vh", backgroundColor: "#f0f2f5", display: "flex", flexDirection: "column", alignItems: "center" }}>
      {/* Navbar */}
      <AppBar position="static">
        <Toolbar>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            SRC E-Voting System
          </Typography>
          <Button color="inherit" onClick={() => navigate("/register")}>
            Sign Up
          </Button>
        </Toolbar>
      </AppBar>

      {/* Hero Section */}
      <Box textAlign="center" mt={5}>
        <Typography variant="h3" fontWeight="bold">
          Your Vote, Your Voice!
        </Typography>
        <Typography variant="h6" color="textSecondary" mt={2}>
          Participate in the SRC elections securely and fairly using our online e-voting system.
        </Typography>
        <Button variant="contained" color="primary" size="large" sx={{ mt: 3 }} onClick={() => navigate("/register")}>
          Get Started
        </Button>
      </Box>

      {/* Election Details Section */}
      <Box sx={{ width: "100%", backgroundColor: "white", boxShadow: 2, p: 4, textAlign: "center", mt: 5 }}>
        <Typography variant="h5" fontWeight="bold">Upcoming Elections</Typography>
        <Typography color="textSecondary">Voting opens on: <strong>March 15, 2025</strong></Typography>
        <Typography color="textSecondary">Voting closes on: <strong>March 16, 2025</strong></Typography>
      </Box>
    </Box>
  );
};

export default HomePage;
